def pre(a, b, c, d, e):
    for v in [a, b, c, d, e]:
        if v < 0 or v > 5:
            return False
    return True


def post(a, b, c, d, e, result):
    vals = [a, b, c, d, e]
    # result must be one of the inputs
    if result not in vals:
        return False
    # The median (3rd smallest, counting repeats) is the value m where
    # at most 2 elements are strictly less than m and at least 3 elements are <= m.
    less = 0
    less_eq = 0
    for v in vals:
        if v < result:
            less += 1
        if v <= result:
            less_eq += 1
    if not (less <= 2 and less_eq >= 3):
        return False
    # Cross-check against the sorted definition
    s = sorted(vals)
    return result == s[2]
